query:
UPDATE blog_posts 
SET 
  imageUrl = NULL,
  content = REGEXP_REPLACE(content, '^!\\[[^\\]]*\\]\\([^)]+\\)\\n*', '')
WHERE id = 30003;
SELECT id, imageUrl, SUBSTRING(content, 1, 300) as content_start FROM blog_posts WHERE id = 30003;

